changeSet.sql:
create table sql_source_content (
	id int primary key not null,
	content longblob not null,
	foreign key (id) references sql_source (id) on update cascade on delete cascade
) row_format = compressed;

create table tag_def (
	name       varchar(255) primary key not null,
	color      varchar(32),
	created_on timestamp not null default current_timestamp
);

alter table tags add column environment_name varchar(255) null;
update tags set environment_name = 'regression';
alter table tags modify environment_name varchar(255) not null;

alter table notes add column environment_name varchar(255) null;
update notes set environment_name = 'regression';
alter table notes modify environment_name varchar(255) not null;
create index notes_env_path on notes (environment_name, path);

delete from tag_def
where name = 'system'
  and not exists (select 1 from (select id from tags where name = 'system') still_used);

alter table tags
	modify column name varchar(48) character set utf8mb4 collate utf8mb4_general_ci not null,
	modify column environment_name varchar(48) not null;
alter table tag_def modify column name varchar(48) not null;
alter table notes modify column environment_name varchar(48) not null;
alter table annotations modify column environment_name varchar(48) not null;
alter table source_ref modify column environment_name varchar(48);
alter table query_example modify column environment_name varchar(48);
